using AFMS.Application.Abstractions;
using AFMS.Application.Models;
using ClosedXML.Excel;

namespace AFMS.Infrastructure.Files;

public sealed class ReportExcelWriter : IReportExcelWriter
{
    public Task WriteAsync(ReportDocument document, string outputPath, CancellationToken cancellationToken = default)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath)!); using var workbook = new XLWorkbook(); var sheet = workbook.Worksheets.Add(SheetName(document.Title));
        sheet.Cell(1, 1).Value = "REPUBLIC OF THE PHILIPPINES"; sheet.Cell(2, 1).Value = $"Province of {document.Province}"; sheet.Cell(3, 1).Value = $"Municipality of {document.Municipality}";
        sheet.Cell(4, 1).Value = document.OfficeName; sheet.Cell(5, 1).Value = document.Title; sheet.Cell(6, 1).Value = "Reporting Period"; sheet.Cell(6, 2).Value = document.ReportingPeriod;
        sheet.Cell(7, 1).Value = "Report Reference"; sheet.Cell(7, 2).Value = document.ReportReference; sheet.Cell(8, 1).Value = "Generated"; sheet.Cell(8, 2).Value = document.GeneratedAt.LocalDateTime;
        sheet.Cell(9, 1).Value = "Generated By"; sheet.Cell(9, 2).Value = document.GeneratedBy; const int headerRow = 11;
        for (var c = 0; c < document.Columns.Count; c++) sheet.Cell(headerRow, c + 1).Value = document.Columns[c].Header;
        var header = sheet.Range(headerRow, 1, headerRow, Math.Max(1, document.Columns.Count)); header.Style.Font.Bold = true; header.Style.Font.FontColor = XLColor.White; header.Style.Fill.BackgroundColor = XLColor.FromHtml("#16324F"); header.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
        for (var r = 0; r < document.Rows.Count; r++)
        for (var c = 0; c < document.Columns.Count; c++)
        {
            cancellationToken.ThrowIfCancellationRequested(); var cell = sheet.Cell(headerRow + 1 + r, c + 1); var value = c < document.Rows[r].Values.Count ? document.Rows[r].Values[c] : null;
            Set(cell, value); ApplyFormat(cell, document.Columns[c].Type);
        }
        var lastDataRow = Math.Max(headerRow, headerRow + document.Rows.Count); if (document.Columns.Count > 0 && document.Rows.Count > 0) sheet.Range(headerRow, 1, lastDataRow, document.Columns.Count).SetAutoFilter();
        sheet.SheetView.FreezeRows(headerRow); var metadataWidth = Math.Max(2, document.Columns.Count);
        for (var row = 1; row <= 5; row++) sheet.Range(row, 1, row, metadataWidth).Merge();
        sheet.Range(1, 1, 5, metadataWidth).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center; sheet.Cell(1, 1).Style.Font.Bold = true; sheet.Cell(5, 1).Style.Font.Bold = true; sheet.Cell(5, 1).Style.Font.FontSize = 14; sheet.Cell(5, 1).Style.Font.FontColor = XLColor.FromHtml("#16324F");
        var summaryRow = lastDataRow + 2; foreach (var summary in document.Summaries) { sheet.Cell(summaryRow, 1).Value = summary.Label; sheet.Cell(summaryRow, 1).Style.Font.Bold = true; sheet.Cell(summaryRow, 2).Value = summary.Value; sheet.Cell(summaryRow, 2).Style.NumberFormat.Format = summary.Format; summaryRow++; }
        summaryRow += 2; sheet.Cell(summaryRow, 1).Value = "Prepared By"; sheet.Cell(summaryRow, 2).Value = document.PreparedBy; sheet.Cell(summaryRow + 1, 1).Value = "Checked By"; sheet.Cell(summaryRow + 1, 2).Value = document.CheckedBy; sheet.Cell(summaryRow + 2, 1).Value = "Certified Correct By"; sheet.Cell(summaryRow + 2, 2).Value = document.CertifiedCorrectBy;
        AutoSize(sheet, document); sheet.Rows().Style.Alignment.Vertical = XLAlignmentVerticalValues.Top; sheet.Rows(headerRow + 1, lastDataRow).Style.Alignment.WrapText = true;
        sheet.PageSetup.PageOrientation = document.Columns.Count > 7 ? XLPageOrientation.Landscape : XLPageOrientation.Portrait; sheet.PageSetup.FitToPages(1, 0); sheet.PageSetup.Footer.Center.AddText($"{document.ReportReference} | Page &[Page] of &[Pages]");
        workbook.Properties.Title = document.Title; workbook.Properties.Author = document.OfficeName; workbook.SaveAs(outputPath); return Task.CompletedTask;
    }

    private static void Set(IXLCell cell, object? value)
    {
        switch (value) { case null: cell.Value = ""; break; case DateOnly d: cell.Value = d.ToDateTime(TimeOnly.MinValue); break; case DateTimeOffset d: cell.Value = d.LocalDateTime; break; case long l: cell.Value = l; break; case int i: cell.Value = i; break; case decimal d: cell.Value = d; break; case double d: cell.Value = d; break; default: cell.Value = value.ToString() ?? ""; break; }
    }
    private static void ApplyFormat(IXLCell cell, ReportValueType type) { if (type == ReportValueType.Date) cell.Style.DateFormat.Format = "mmm d, yyyy"; else if (type == ReportValueType.DateTime) cell.Style.DateFormat.Format = "mmm d, yyyy h:mm AM/PM"; else if (type == ReportValueType.Integer) cell.Style.NumberFormat.Format = "#,##0"; else if (type == ReportValueType.Decimal) cell.Style.NumberFormat.Format = "#,##0.00"; }
    private static void AutoSize(IXLWorksheet sheet, ReportDocument document)
    {
        for (var columnIndex = 0; columnIndex < document.Columns.Count; columnIndex++)
        {
            var width = document.Columns[columnIndex].Header.Length;
            foreach (var row in document.Rows)
            {
                var value = columnIndex < row.Values.Count ? row.Values[columnIndex] : null;
                width = Math.Max(width, value?.ToString()?.Length ?? 0);
            }
            sheet.Column(columnIndex + 1).Width = Math.Clamp(width + 2, 10, 45);
        }
        if (document.Columns.Count < 2) sheet.Column(2).Width = 24;
    }
    private static string SheetName(string value) { var invalid = new[] { ':', '\\', '/', '?', '*', '[', ']' }; var clean = string.Concat(value.Select(c => invalid.Contains(c) ? '-' : c)); return clean.Length <= 31 ? clean : clean[..31]; }
}
